select set_config('request.jwt.claims',jsonb_build_object('sub',(select coalesce(auth_id,gen_random_uuid()) from public.users where id='928d3473-49a2-4427-a319-19729689a084'),'email','admin@khoviet.vn','role','authenticated')::text,true);
set local role authenticated;
do $$ declare cal jsonb; r jsonb; s jsonb:='{"type": "department", "departmentId": "6a1ee524-c7f6-41dd-9b0d-440e76c6cdc9"}'::jsonb; begin
 if public.current_app_user_id() is distinct from '928d3473-49a2-4427-a319-19729689a084'::uuid then raise exception 'WORK_PILOT_IDENTITY_MISMATCH';end if;
 cal:=public.save_work_configuration('calendar',s,null,null,'{"name": "Văn phòng — Phòng Quản lý dự án", "timezone": "Asia/Ho_Chi_Minh", "working_weekdays": [1, 2, 3, 4, 5, 6], "working_intervals": [{"start": "08:00", "end": "12:00"}, {"start": "13:00", "end": "17:00"}], "is_default": false, "is_active": true}'::jsonb,'Vioo Work R1A named pilot — Phòng Quản lý dự án','553f600f-ade6-4e33-a2c0-28650af33a1c');
 perform public.save_work_configuration('policy',s,null,null,'{"name": "Pilot QLDA — normal", "priority": "normal", "acknowledgement_minutes": 480, "execution_minutes": null, "effective_from": "2026-09-07T00:00:00+07:00", "is_active": true}'::jsonb||jsonb_build_object('calendar_id',cal->>'id'),'Vioo Work R1A named pilot — Phòng Quản lý dự án','cf3587d0-0acd-414b-985c-b5a003a30b25');
 perform public.save_work_configuration('policy',s,null,null,'{"name": "Pilot QLDA — important", "priority": "important", "acknowledgement_minutes": 240, "execution_minutes": null, "effective_from": "2026-09-07T00:00:00+07:00", "is_active": true}'::jsonb||jsonb_build_object('calendar_id',cal->>'id'),'Vioo Work R1A named pilot — Phòng Quản lý dự án','d8293151-2d3c-4d99-84cf-6f4da289423f');
 perform public.save_work_configuration('policy',s,null,null,'{"name": "Pilot QLDA — urgent", "priority": "urgent", "acknowledgement_minutes": 60, "execution_minutes": null, "effective_from": "2026-09-07T00:00:00+07:00", "is_active": true}'::jsonb||jsonb_build_object('calendar_id',cal->>'id'),'Vioo Work R1A named pilot — Phòng Quản lý dự án','f7a23a2d-330b-42e4-9f42-50b4c71910f4');
 r:=public.preview_work_configuration_sla(s,'urgent','2026-09-07T11:30:00+07:00');
 if (r->>'acknowledgementDueAt')::timestamptz<>'2026-09-07T13:30:00+07:00'::timestamptz then raise exception 'WORK_PILOT_LUNCH_MISMATCH';end if;
 r:=public.preview_work_configuration_sla(s,'normal','2026-09-12T16:00:00+07:00');
 if (r->>'acknowledgementDueAt')::timestamptz<>'2026-09-14T16:00:00+07:00'::timestamptz then raise exception 'WORK_PILOT_WEEKEND_MISMATCH';end if;
