do $$ declare u uuid; begin
 for u in select id from public.users where email in ('admin@khoviet.vn','sonpn@tienthinhjsc.vn') loop
 if not app_private.has_permission(u,'work.module.access','global','*') or not app_private.has_permission(u,'work.task.create','department','6a1ee524-c7f6-41dd-9b0d-440e76c6cdc9') or not app_private.has_permission(u,'work.task.view_related','department','6a1ee524-c7f6-41dd-9b0d-440e76c6cdc9') then raise exception 'WORK_PILOT_GRANT_MISSING';end if;
 if app_private.has_permission(u,'work.task.configure','global','*') then raise exception 'WORK_PILOT_GLOBAL_CONFIG';end if;
 end loop;
 if app_private.has_permission('d0a300a0-1586-4748-b6e7-71773addc004','work.task.configure','department','6a1ee524-c7f6-41dd-9b0d-440e76c6cdc9') then raise exception 'WORK_PILOT_MEMBER_CONFIG';end if;
end $$;
select 'WORK_NAMED_DEV_PILOT_READY' as result;
rollback;
